let eventGuid = 0
// let todayStr = new Date().toISOString().replace(/T.*$/, '') // YYYY-MM-DD of today
function formatDate() {

    let now = new Date();

    let year = now.getFullYear();
    let month = (now.getMonth() + 1).toString().padStart(2, '0'); // збереження формату MM
    let day = now.getDate().toString().padStart(2, '0'); // збереження формату DD

    let hours = now.getHours().toString().padStart(2, '0');
    let minutes = now.getMinutes().toString().padStart(2, '0');
    let seconds = now.getSeconds().toString().padStart(2, '0');
    let milliseconds = now.getMilliseconds();

    // Формування рядка часової зони
    let timezoneOffset = -now.getTimezoneOffset();
    let sign = timezoneOffset >= 0 ? '+' : '-';
    let offsetHours = Math.floor(Math.abs(timezoneOffset) / 60).toString().padStart(2, '0');
    let offsetMinutes = (Math.abs(timezoneOffset) % 60).toString().padStart(2, '0');

    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds} ${sign}${offsetHours}${offsetMinutes}`;
}
let todayStr = formatDate(); // Формування рядка дати згідно формату "YYYY-MM-DD HH:MM:SS.mmmmmm +ZZZZ"

export const INITIAL_EVENTS = [
    {
        id: createEventId(),
        title: 'All-day event',
        start: todayStr
    },
    {
        id: createEventId(),
        title: 'Timed event',
        start: todayStr + 'T12:00:00'
    }
]

export function createEventId() {
    return String(eventGuid++)
}
